#[no_mangle]
pub unsafe extern "C" fn tinfl_decompress(
    mut r: *mut tinfl_decompressor,
    mut pIn_buf_next: *const mz_uint8,
    mut pIn_buf_size: *mut size_t,
    mut pOut_buf_start: *mut mz_uint8,
    mut pOut_buf_next: *mut mz_uint8,
    mut pOut_buf_size: *mut size_t,
    decomp_flags: mz_uint32,
) -> tinfl_status {

use std::hint::black_box;
use std::time::Instant;

use miniz_raw::src::miniz_tdef::{
    tdefl_compress_mem_to_mem, tdefl_create_comp_flags_from_zip_params, MZ_DEFAULT_STRATEGY,
    TDEFL_COMPUTE_ADLER32,
};
use miniz_raw::src::miniz_tinfl::{
    tinfl_decompress_mem_to_mem, TINFL_DECOMPRESS_MEM_TO_MEM_FAILED, TINFL_FLAG_PARSE_ZLIB_HEADER,
};

fn build_input() -> Vec<u8> {
    let mut data = Vec::with_capacity(8 * 1024 * 1024);
    let mut state = 0x1234_5678u32;

    for block in 0..8192u32 {
        let line = format!(
            "path=/assets/{:03}/chunk/{:05} kind=text repeat={} ",
            block % 97,
            block,
            block % 11
        );
        for _ in 0..8 {
            data.extend_from_slice(line.as_bytes());
            data.extend_from_slice(
                b"The quick brown fox jumps over the lazy dog. miniz translated by c2rust. ",
            );
        }

        for i in 0..256u32 {
            state = state.wrapping_mul(1664525).wrapping_add(1013904223);
            data.push(((state >> 24) as u8) ^ (block as u8).wrapping_mul(31) ^ (i as u8));
        }

        let tag = (block % 251) as u8;
        for _ in 0..(384 + (block % 5) * 64) {
            data.push(tag);
        }
    }

    data
}

unsafe fn compress_once(input: &[u8], output: &mut [u8], flags: i32) -> usize {
    tdefl_compress_mem_to_mem(
        output.as_mut_ptr().cast(),
        output.len(),
        input.as_ptr().cast(),
        input.len(),
        flags,
    )
}

unsafe fn decompress_once(input: &[u8], output: &mut [u8]) -> usize {
    tinfl_decompress_mem_to_mem(
        output.as_mut_ptr().cast(),
        output.len(),
        input.as_ptr().cast(),
        input.len(),
        TINFL_FLAG_PARSE_ZLIB_HEADER as i32,
    )
}

fn main() {
    let input = build_input();
    let mut compressed = vec![0u8; input.len() * 2];
    let mut restored = vec![0u8; input.len()];

    let flags = unsafe {
        tdefl_create_comp_flags_from_zip_params(6, 15, MZ_DEFAULT_STRATEGY as i32) as i32
            | TDEFL_COMPUTE_ADLER32 as i32
    };

    let compressed_len = unsafe { compress_once(&input, &mut compressed, flags) };
    assert!(compressed_len > 0, "compression failed");
    let restored_len = unsafe { decompress_once(&compressed[..compressed_len], &mut restored) };
    assert_ne!(
        restored_len, TINFL_DECOMPRESS_MEM_TO_MEM_FAILED,
        "decompression failed"
    );
    assert_eq!(restored_len, input.len(), "unexpected decompressed size");
    assert_eq!(restored, input, "roundtrip mismatch");

    for _ in 0..3 {
        black_box(unsafe { compress_once(&input, &mut compressed, flags) });
        black_box(unsafe { decompress_once(&compressed[..compressed_len], &mut restored) });
    }

    let compress_iters = 12;
    let decompress_iters = 60;

    let compress_start = Instant::now();
    let mut last_compressed_len = 0usize;
    for _ in 0..compress_iters {
        last_compressed_len = unsafe { compress_once(&input, &mut compressed, flags) };
        black_box(last_compressed_len);
    }
    let compress_elapsed = compress_start.elapsed();

    let decompress_start = Instant::now();
    let mut last_restored_len = 0usize;
    for _ in 0..decompress_iters {
        last_restored_len =
            unsafe { decompress_once(&compressed[..compressed_len], &mut restored) };
        black_box(last_restored_len);
        black_box(restored[0]);
    }
    let decompress_elapsed = decompress_start.elapsed();

    println!("input_bytes={}", input.len());
    println!("compressed_bytes={}", compressed_len);
    println!("compress_iters={}", compress_iters);
    println!("compress_total_ms={:.3}", compress_elapsed.as_secs_f64() * 1000.0);
    println!(
        "compress_mb_s={:.3}",
        (input.len() * compress_iters) as f64 / (1024.0 * 1024.0) / compress_elapsed.as_secs_f64()
    );
    println!("decompress_iters={}", decompress_iters);
    println!(
        "decompress_total_ms={:.3}",
        decompress_elapsed.as_secs_f64() * 1000.0
    );
    println!(
        "decompress_mb_s={:.3}",
        (input.len() * decompress_iters) as f64
            / (1024.0 * 1024.0)
            / decompress_elapsed.as_secs_f64()
    );
    println!("last_compressed_len={}", last_compressed_len);
    println!("last_restored_len={}", last_restored_len);
}
